) v(nn, nm, hd, ncc, ma, sl, dg, tt, kho, gc)
JOIN cong_ty c ON c.ma = 'DEMO'
JOIN hang_hoa h ON h.cong_ty_id = c.id AND h.ma = v.ma
LEFT JOIN doi_tac d ON d.cong_ty_id = c.id AND d.loai = 'NCC' AND d.ten = v.ncc;
-- Nối dòng tách hóa đơn (✂ Tách) với dòng gốc cùng số HĐ + mã hàng
UPDATE mua_hang m SET tach_tu_id = g.id
FROM mua_hang g
WHERE m.cong_ty_id = (SELECT id FROM cong_ty WHERE ma = 'DEMO') AND g.cong_ty_id = m.cong_ty_id AND m.ghi_chu LIKE 'Tách từ dòng%'
  AND g.so_hoa_don = m.so_hoa_don AND g.hang_hoa_id = m.hang_hoa_id AND g.id <> m.id AND g.ghi_chu IS DISTINCT FROM m.ghi_chu;

